import React, { useEffect, useRef, useState } from "react";
import { useSearchParams, useNavigate } from "react-router-dom";
import { useUI } from "../context/UIContext";
import Button from "../components/common/Button";
import Card from "../components/common/Card";
import styles from "../SDM.module.css";
import eveVideo from "../assets/eve_sdm_talk.mp4";
import { topicDescriptions } from "../constants/sdm";

const SDM = () => {
  const [searchParams, setSearchParams] = useSearchParams();
  const navigate = useNavigate();
  const { setHeroData, allAnswers } = useUI();
  const videoRef = useRef(null);

  const step = searchParams.get("step") || "SELECT";
  const selectedTopicId = searchParams.get("topic");

  const [isPlaying, setIsPlaying] = useState(false);
  const [isPaused, setIsPaused] = useState(false);
  const [currentSubtitle, setCurrentSubtitle] = useState("");
  const [sentences, setSentences] = useState([]);

  // 1. 初始化：確保影片自動播放且靜音
  useEffect(() => {
    setHeroData(null);
    if (videoRef.current) {
      videoRef.current.muted = true;
      videoRef.current
        .play()
        .catch((e) => console.log("Video auto-play blocked", e));
    }
  }, [setHeroData]);

  // 2. 語音邏輯：只有在步驟切換時啟動語音
  useEffect(() => {
    if (step === "SELECT" && !selectedTopicId) {
      prepareAndPlay(
        `${allAnswers.userName || "您"}您好，請選擇您想了解的乳癌治療決策輔助主題。`,
      );
    } else if (step === "INTRO" && selectedTopicId) {
      const content = topicDescriptions[selectedTopicId]?.content || "";
      const cleanText = content
        .replace(/<[^>]+>/g, "")
        .replace(/<br\s*\/?>/g, " ");
      prepareAndPlay(cleanText);
    }
    return () => window.speechSynthesis.cancel();
  }, [step, selectedTopicId, allAnswers.userName]);

  const prepareAndPlay = (text) => {
    const sentenceArray = text.match(/[^。？！，、]+[。？！，、]?/g) || [text];
    let accumulatedLength = 0;
    const mapped = sentenceArray.map((s) => {
      const start = accumulatedLength;
      accumulatedLength += s.length;
      return { text: s.trim(), start, end: accumulatedLength };
    });
    setSentences(mapped);
    handlePlaySpeech(text, mapped);
  };

  const handlePlaySpeech = (text, currentSentences) => {
    window.speechSynthesis.cancel();
    const utterance = new SpeechSynthesisUtterance(text);
    utterance.lang = "zh-TW";
    utterance.onstart = () => {
      setIsPlaying(true);
      setIsPaused(false);
    };
    utterance.onboundary = (e) => {
      const active = currentSentences.find(
        (s) => e.charIndex >= s.start && e.charIndex < s.end,
      );
      if (active) setCurrentSubtitle(active.text);
    };
    utterance.onend = () => {
      setIsPlaying(false);
      setCurrentSubtitle("");
    };
    window.speechSynthesis.speak(utterance);
  };

  // 3. 獨立控制邏輯
  const handleTogglePlay = () => {
    // 控制影片
    if (videoRef.current) {
      if (videoRef.current.paused) videoRef.current.play();
      else videoRef.current.pause();
    }
    // 控制語音
    if (isPlaying) {
      if (isPaused) {
        window.speechSynthesis.resume();
        setIsPaused(false);
      } else {
        window.speechSynthesis.pause();
        setIsPaused(true);
      }
    }
  };

  const topics = Object.keys(topicDescriptions).map((key) => ({
    id: key,
    ...topicDescriptions[key],
  }));

  return (
    <div className={styles.pageContainer}>
      <div className={styles.interactiveCard}>
        <div className={styles.videoSection}>
          <video
            ref={videoRef}
            src={eveVideo}
            playsInline
            loop
            className={styles.theatreVideo}
          />
          {isPlaying && currentSubtitle && (
            <div className={styles.subtitleOverlay}>
              <p className={styles.subtitleText}>{currentSubtitle}</p>
            </div>
          )}
          <button
            className={styles.controlBtnTopRight}
            onClick={handleTogglePlay}
          >
            {isPlaying && !isPaused ? "⏸ 暫停" : "▶️ 播放"}
          </button>
        </div>

        <div className={styles.contentSection}>
          {step === "SELECT" ? (
            <>
              {topics.map((item) => (
                <Card
                  key={item.id}
                  title={item.label}
                  description={item.description}
                  isActive={selectedTopicId === item.id}
                  // 🌟 關鍵：點擊卡片不再呼叫 cancel()，也不影響影片
                  onClick={() =>
                    setSearchParams({ step: "SELECT", topic: item.id })
                  }
                />
              ))}
              <Button
                onClick={() =>
                  selectedTopicId &&
                  setSearchParams({ step: "INTRO", topic: selectedTopicId })
                }
                fullWidth
                disabled={!selectedTopicId}
              >
                確認選擇並查看詳情 ➔
              </Button>
              <Button
                variant="outline"
                onClick={() => navigate(-1)}
                fullWidth
                style={{ marginTop: "10px" }}
              >
                返回上一頁
              </Button>
            </>
          ) : (
            <div>
              <div
                dangerouslySetInnerHTML={{
                  __html: topicDescriptions[selectedTopicId]?.content,
                }}
              />
              <Button
                variant="outline"
                onClick={() => {
                  window.speechSynthesis.cancel();
                  setSearchParams({ step: "SELECT" });
                }}
                fullWidth
              >
                返回選擇主題
              </Button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default SDM;
